<?php
declare(strict_types=1);require_once __DIR__.'/../src/session.php';
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LSZJ QR-Login</title><link rel="stylesheet" href="app.css"><style>.wrap{max-width:720px;margin:30px auto;padding:0 12px}.qr{display:block;width:min(320px,100%);height:auto;margin:18px auto;border:1px solid #d9e0e8}.status{padding:14px;border-left:5px solid #1769aa;background:#eef6fc;border-radius:8px}.bad{border-color:#b00020;background:#fff0f0;color:#970018}</style></head><body><main class="wrap"><h1>Mit Smartphone anmelden</h1><section class="card"><p>QR-Code mit dem persönlichen Smartphone scannen und die Anmeldung dort bestätigen.</p><button id="create" type="button">QR-Code erzeugen</button><img id="qr" class="qr" alt="QR-Code für die C-Büro-Anmeldung" hidden><div id="status" class="status" hidden></div></section></main><script>
const csrf=<?=json_encode(csrf_token(),JSON_THROW_ON_ERROR)?>;let token=null,timer=null;const q=document.getElementById('qr'),s=document.getElementById('status'),b=document.getElementById('create');function show(m,e=false){s.hidden=false;s.className='status'+(e?' bad':'');s.textContent=m;}async function poll(){if(!token)return;try{const r=await fetch('api_qr_login_status.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:csrf,token})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Statusfehler.');show('Status: '+j.session.status);if(j.session.status!=='pending'){clearInterval(timer);timer=null;}}catch(e){show(e.message||String(e),true);clearInterval(timer);timer=null;}}
b.addEventListener('click',async()=>{b.disabled=true;try{const r=await fetch('api_qr_login_create.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:csrf})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Session konnte nicht erzeugt werden.');token=j.session.token;q.src='api_qr_login_code.php?token='+encodeURIComponent(token);q.hidden=false;show('Status: pending. Gültig bis '+j.session.expires_at);if(timer)clearInterval(timer);timer=setInterval(poll,2000);}catch(e){show(e.message||String(e),true);b.disabled=false;}});
</script></body></html>
